                        continue
                    if c1 != 0 and any(grid[r][c1] != fg for r in range(r1, r2 + 1)):
                        continue
                    if c2 != w - 1 and any(grid[r][c2] != fg for r in range(r1, r2 + 1)):
                        continue

                    # Canvas edges can act as an open side of the outlined region.
                    top = r1 if r1 == 0 and grid[r1][c1] == bg else r1 + 1
                    bottom = r2 if r2 == h - 1 and grid[r2][c1] == bg else r2 - 1
                    left = c1 if c1 == 0 and grid[r1][c1] == bg else c1 + 1
                    right = c2 if c2 == w - 1 and grid[r1][c2] == bg else c2 - 1

                    if top > bottom or left > right:
                        continue
                    if all(grid[r][c] == bg
                           for r in range(top, bottom + 1)
                           for c in range(left, right + 1)):
                        for r in range(top, bottom + 1):
                            for c in range(left, right + 1):
                                out[r][c] = 4
    return out
